@page "/notifications"
@using NotificationsApp.Services
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>#@notification.Id</strong> &mdash; @notification.Message
                </div>
                <small class="text-muted">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // OnInitialized runs during BOTH prerender and interactive render.
    // Load data here so it appears in the initial server-rendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
    }

    // OnAfterRenderAsync with firstRender==true fires only once the component
    // is live and interactive in the browser — never during static SSR prerender.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate the server producing a new notification each poll cycle
            NotificationSvc.SimulateNewNotification();

            var lastId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
            var newItems = NotificationSvc.GetSince(lastId);

            if (newItems.Count > 0)
            {
                _notifications.AddRange(newItems);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

